"""Calculates chao1 variance, bias-corrected.

    From EstimateS manual, equation 6.
    """
def chao1_var_bias_corrected(singles: Any, doubles: Any) -> object {
    (s, d) = (float(singles), float(doubles));
    return (
        ((s * (s - 1)) / (2 * (d + 1)))
        + ((s * (((2 * s) - 1) ** 2)) / (4 * ((d + 1) ** 2)))
        + (((s ** 2) * d * ((s - 1) ** 2)) / (4 * ((d + 1) ** 4)))
    );
}

"""Picks out elements of the document summary from Entrez"""
def fetch_parts(summary: Any) -> object {
    AssemblyAccession = summary["AssemblyAccession"];
    AssemblyStatus = summary["AssemblyStatus"];
    WGS = summary["WGS"];
    Coverage = summary["Coverage"];
    SubmissionDate = summary["SubmissionDate"];
    LastUpdateDate = summary["LastUpdateDate"];
    biosampleID = summary["BioSampleId"];
    return (
        AssemblyAccession,
        AssemblyStatus,
        WGS,
        Coverage,
        SubmissionDate,
        LastUpdateDate,
        biosampleID
    );
}

